data.document:
query MexFetchRecommendedNewslettersJobQuery($fetch_status_metadata, $input) {
  id
  type
  text
  update_time
  xwa2_newsletters_recommended {
    page_info {
      hasNextPage
      hasPreviousPage
      startCursor
      endCursor
      result {
        state {
          thread_metadata {
            creation_time
            name {
              description {
                picture {
                  direct_path
                  invite
                  handle
                  verification
                  subscribers_count
                  status_metadata {
                    last_status_server_id
                    last_status_sent_time
                  }
                }
              }
            }
          }
        }
      }
    }
  }
}
